```csharp
using UnityEngine;
using UnityEngine.XR.Interaction.Toolkit;
using Photon.Pun;

public class NetworkXRInteractable : XRInteractable, IPunObservable
{
    private PhotonView photonView;

    protected override void Awake()
    {
        base.Awake();
        photonView = GetComponent<PhotonView>();
    }

    public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
    {
        if (stream.IsWriting)
        {
            // Write the interactable's state to the stream
            stream.SendNext(transform.position);
            stream.SendNext(transform.rotation);
            stream.SendNext(isSelected);
        }
        else
        {
            // Read the interactable's state from the stream
            transform.position = (Vector3)stream.ReceiveNext();
            transform.rotation = (Quaternion)stream.ReceiveNext();
            isSelected = (bool)stream.ReceiveNext();
        }
    }
}
```

