```csharp
using UnityEngine;
using Photon.Pun;

public class NetworkAudioSource : Photon.PunBehaviour, IPunObservable
{
    private PhotonView photonView;

    public AudioClip clip;
    public float volume = 1.0f;
    public float pitch = 1.0f;

    protected override void Awake()
    {
        base.Awake();
        photonView = GetComponent<PhotonView>();
        if (photonView.IsMine)
        {
            gameObject.AddComponent<AudioSource>().Setup(clip, volume, pitch);
        }
    }

    public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
    {
        if (stream.IsWriting)
        {
            // Write the audio source's state to the stream
            stream.SendNext(volume);
            stream.SendNext(pitch);
        }
        else
        {
            // Read the audio source's state from the stream
            volume = (float)stream.ReceiveNext();
            pitch = (float)stream.ReceiveNext();
            if (photonView.IsMine)
            {
                var audioSource = GetComponent<AudioSource>();
                audioSource.volume = volume;
                audioSource.pitch = pitch;
            }
        }
    }
}
```

