        if tail[0] < head[0]:
            tail[0] += 1
        elif tail[0] > head[0]:
            tail[0] -= 1
        if tail[1] < head[1]:
            tail[1] += 1
        elif tail[1] > head[1]:
            tail[1] -= 1
    return tail

