```
import java.util.*

class Minesweeper {
    private val board: Array<Array<Int>>
    private val rows: Int
    private val cols: Int
    private val mines: Int
    private val revealed: Array<Array<Boolean>>

    constructor(rows: Int, cols: Int, mines: Int) {
        this.rows = rows
        this.cols = cols
        this.mines = mines
        board = Array(rows) { Array(cols) { 0 } }
        revealed = Array(rows) { Array(cols) { false } }
        placeMines()
    }

    private fun placeMines() {
        val random = Random()
        var minesPlaced = 0
        while (minesPlaced < mines) {
            val row = random.nextInt(rows)
            val col = random.nextInt(cols)
            if (board[row][col] == 0) {
                board[row][col] = -1
                minesPlaced++
            }
        }
    }

    fun revealCell(row: Int, col: Int): Boolean {
        if (revealed[row][col]) return false
        revealed[row][col] = true
        if (board[row][col] == -1) {
            return true // game over
        }
        return false
    }

    fun getCell(row: Int, col: Int): Int {
        return board[row][col]
    }

    fun getRevealed(row: Int, col: Int): Boolean {
        return revealed[row][col]
    }

    fun getAdjacentMines(row: Int, col: Int): Int {
        var count = 0
        for (i in -1..1) {
            for (j in -1..1) {
                if (i == 0 && j == 0) continue
                val r = row + i
                val c = col + j
                if (r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] == -1) {
                    count++
                }
            }
        }
        return count
    }

    fun printBoard() {
        for (i in 0 until rows) {
            for (j in 0 until cols) {
                if (revealed[i][j]) {
                    if (board[i][j] == -1) {
                        print("X ")
                    } else {
                        print("${getCell(i, j)} ")
                    }
                } else {
                    print("? ")
                }
            }
            println()
        }
    }
}

fun main() {
    val game = Minesweeper(10, 10, 20)
    while (true) {
        game.printBoard()
        println("Enter row and column (or 'q' to quit):")
        val input = readLine()!!
        if (input == "q") break
        val parts = input.split(" ")
        val row = parts[0].toInt()
        val col = parts[1].toInt()
        if (game.revealCell(row, col)) {
            println("Game over!")
            break
        }
    }
}
```
