		case event, ok := <-watch.ResultChan():
			if !ok {
				return
			}

			switch event.Type {
			case watch.Added, watch.Modified:
				o.queue.Add(event.Object)
			default:
				// Ignore other event types
			}
		case <-stopCh:
			return
		}
	}
}

