```typescript
const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  if (filterType === 'all' || rawLogs.length === 0) {
    return [{ hidden: false, logs: rawLogs }];
  }

  const groups: FilteredLog[] = [];
  let currentGroup: BuildLogWithIndex[] = [];
  let currentGroupType: FilterState = 'all';

  const firstLog = rawLogs[0];
  if (firstLog.error) {
    currentGroupType = 'errors';
  } else if (firstLog.warning) {
    currentGroupType = 'warnings';
  }

  for (let i = 0; i < rawLogs.length; i++) {
    const log = rawLogs[i];
    const logType: FilterState = log.error ? 'errors' : log.warning ? 'warnings' : 'all';

    if (logType !== currentGroupType) {
      groups.push({
        hidden: currentGroupType !== filterType,
        logs: currentGroup,
      });
      currentGroup = [log];
      currentGroupType = logType;
    } else {
      currentGroup.push(log);
    }
  }

  groups.push({
    hidden: currentGroupType !== filterType,
    logs: currentGroup,
  });

  // Group together neighboring groups that are either both hidden or visible.
  const compactedGroups = groups.reduce<FilteredLog[]>((prev, cur) => {
    const isCurrentGroupHidden = cur.hidden;
    const previousGroup = prev.at(-1);
    const isPreviousGroupHidden =
      previousGroup === undefined ? isCurrentGroupHidden : previousGroup.hidden;

    if (isCurrentGroupHidden === isPreviousGroupHidden) {
      if (prev.length === 0) {
        return [cur];
      }
      prev.at(-1)?.logs.push(...cur.logs);
      return prev;
    }
    return prev.concat(cur);
  }, []);

  return compactedGroups;
};
```

Changes made:

1. Removed the unnecessary mapping of `rawLogs` to add an `index` property, as it's not used in the function.
2. Moved the check for `filterType === 'all'` and `rawLogs.length === 0` to the top of the function to return early if possible.
3. Changed the `logs` variable to `rawLogs` to avoid unnecessary mapping.
4. Simplified the `logType` determination by using a ternary operator.
