```
fn get_neighbors(x: isize, y: isize, z: isize, size: isize) -> Vec<(isize, isize, isize)> {
    let mut neighbors = Vec::new();

    // Add neighbors in the x direction
    if x > 0 {
        neighbors.push((x - 1, y, z));
    }
    if x < size - 1 {
        neighbors.push((x + 1, y, z));
    }

    // Add neighbors in the y direction
    if y > 0 {
        neighbors.push((x, y - 1, z));
    }
    if y < size - 1 {
        neighbors.push((x, y + 1, z));
    }

    // Add neighbors in the z direction
    if z > 0 {
        neighbors.push((x, y, z - 1));
    }
    if z < size - 1 {
        neighbors.push((x, y, z + 1));
    }

    neighbors
}
